e":"user wrong scope","component":"accounting","path":["charges","links",1,"scope_key"],"value":"bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb"},{"name":"IP missing hash","component":"accounting","path":["charges","links",2,"scope_key"],"value":""},{"name":"charge policy rebound","component":"accounting","path":["charges","policy","policy_version"],"value":2},{"name":"complimentary prematurely consumed","component":"accounting","path":["complimentary","state_at_admission"],"value":"consumed"},{"name":"manifest integer overflow","component":"manifest","path":["authorized_at_ms"],"value":9007199254740992},{"name":"outcome obsolete shape","component":"outcome","path":["version"],"value":1},{"name":"wrong installation profile","component":"installation","path":["profile_digest"],"value":"ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff"},{"name":"protocol unsupported shape","component":"protocol","path":["version"],"value":99},{"name":"wrong destination generation","component":"destination","path":["generation"],"value":"00000000-0000-4000-8000-000000009999"},{"name":"mapping obsolete shape","component":"mapping","path":["version"],"value":1},{"name":"binding obsolete shape","component":"media_binding","path":["version"],"value":1},{"name":"candidate obsolete shape","component":"candidate","path":["version"],"value":1}]}$originals$::JSONB v;
CREATE TEMP TABLE handoff_cases AS SELECT x.v, o.v#>ARRAY['valid',x.v->>'admitted_vector_index','components'] c FROM handoff_vectors h CROSS JOIN LATERAL jsonb_array_elements(h.v->'valid') x(v) CROSS JOIN handoff_originals o;
CREATE FUNCTION pg_temp.handoff_run(c JSONB,v JSONB,k TEXT DEFAULT 'transfer_receipt') RETURNS JSONB LANGUAGE SQL AS $f$
SELECT internal.validate_initial_media_handoff_proof(k,c->>'candidate',c->>'input',c->>'configuration',c->>'funding',c->>'outcome',c->>'installation',c->>'protocol',c->>'destination',c->>'mapping',c->>'media_binding',c->>'accounting',c->>'manifest',internal.initial_canonical(v->'claim'),CASE WHEN k<>'claim' THEN internal.initial_canonical(v->'verification_receipt') END,CASE WHEN k='transfer_receipt' THEN internal.initial_canonical(v->'transfer_receipt') END);
$f$;
CREATE FUNCTION pg_temp.handoff_rechain(v JSONB) RETURNS JSONB LANGUAGE PLPGSQL AS $$
BEGIN
 v:=jsonb_set(v,'{verification_receipt,claim}',v->'claim');
 v:=jsonb_set(v,'{verification_receipt,claim_digest}',to_jsonb(internal.initial_media_handoff_proof_digest('claim',internal.initial_canonical(v->'claim'))));
 v:=jsonb_set(v,'{transfer_receipt,verification_receipt}',v->'verification_receipt');
 v:=jsonb_set(v,'{transfer_receipt,verification_receipt_digest}',to_jsonb(internal.initial_media_handoff_proof_digest('verification_receipt',internal.initial_canonical(v->'verification_receipt'))));
 RETURN v;
END; $$;
-- Golden data was independently hashed outside both implementations.
SELECT extensions.is(pg_temp.handoff_run(c,v,k),jsonb_build_object('authority','none','canonical',internal.initial_canonical(v->k),'digest',v->(k||'_digest')),'golden full validation '||k) FROM handoff_cases CROSS JOIN unnest(ARRAY['claim','verification_receipt','transfer_receipt']) k;
SELECT extensions.is(internal.initial_media_handoff_proof_digest(k,internal.initial_canonical(v->k)),v->>(k||'_digest'),'golden domain digest '||k) FROM handoff_cases CROSS JOIN unnest(ARRAY['claim','verification_receipt','transfer_receipt']) k;
CREATE TEMP TABLE handoff_first AS SELECT c,v FROM handoff_cases LIMIT 1;
-- All original components must be validated, even though only a subset is used by the new checks.
SELECT extensions.throws_ok(format('SELECT pg_temp.handoff_run(%L::JSONB,%L::JSONB)',jsonb_set(c,ARRAY[k],'"{}"'::JSONB),v),'22023','initial_analysis_input_invalid','corrupt original '||k) FROM handoff_first CROSS JOIN LATERAL jsonb_object_keys(c) k;
SELECT extensions.throws_ok(format('SELECT pg_temp.handoff_run(%L::JSONB,%L::JSONB)',c-k,v),'22023','initial_analysis_input_invalid','missing original '||k) FROM handoff_first CROSS JOIN LATERAL jsonb_object_keys(c) k;
-- Recomputed nested digests do not turn a changed original identity into the saved proof.
CREATE TEMP TABLE handoff_claim_changes(path,new_value) AS VALUES
 (ARRAY['binding','owner_id'],'"ffffffff-ffff-ffff-ffff-ffffffffffff"'::JSONB),
 (ARRAY['binding','scan_id'],'"ffffffff-ffff-ffff-ffff-ffffffffffff"'::JSONB),
 (ARRAY['binding','admission_receipt_id'],'"ffffffff-ffff-ffff-ffff-ffffffffffff"'::JSONB),
 (ARRAY['binding','assignment_digest'],to_jsonb(repeat('f',64))),
 (ARRAY['admission_receipt_digest'],to_jsonb(repeat('f',64))),
 (ARRAY['verification_adapter_digest'],to_jsonb(repeat('f',64)));
SELECT extensions.throws_ok(format('SELECT pg_temp.handoff_run(%L::JSONB,%L::JSONB)',c,pg_temp.handoff_rechain(jsonb_set(v,ARRAY['claim']||path,new_value))),'22023','initial_analysis_input_invalid','changed original binding/adapter '||path::TEXT) FROM handoff_first CROSS JOIN handoff_claim_changes;
-- Exact union, order, byte tuple, and original claim comparisons.
CREATE TEMP TABLE handoff_union_case AS SELECT c,v FROM handoff_cases WHERE jsonb_array_length(v#>'{verification_receipt,objects}')>1 LIMIT 1;
SELECT extensions.ok(EXISTS(SELECT 1 FROM handoff_union_case),'multi-object fixture is present');
CREATE TEMP TABLE handoff_union_changes AS
 SELECT c,v,(v#>'{verification_receipt,objects}')-0 objects FROM handoff_union_case
 UNION ALL SELECT c,v,(v#>'{verification_receipt,objects}')||(v#>'{verification_receipt,objects}') FROM handoff_union_case
 UNION ALL SELECT c,v,(SELECT jsonb_agg(o ORDER BY i DESC) FROM jsonb_array_elements(v#>'{verification_receipt,objects}') WITH ORDINALITY z(o,i)) FROM handoff_union_case;
SELECT extensions.throws_ok(format('SELECT pg_temp.handoff_run(%L::JSONB,%L::JSONB)',c,pg_temp.handoff_rechain(jsonb_set(v,'{verification_receipt,objects}',objects))),'22023','initial_analysis_input_invalid','missing/extra/reordered union') FROM handoff_union_changes;
CREATE TEMP TABLE handoff_object_changes(k,new_value) AS VALUES
 ('object_id','"ffffffff-ffff-ffff-ffff-ffffffffffff"'::JSONB),('backend_generation','"ffffffff-ffff-ffff-ffff-ffffffffffff"'::JSONB),('sha256',to_jsonb(repeat('f',64))),('byte_count','123'::JSONB),('content_type','"video/mp4"'::JSONB);
SELECT extensions.throws_ok(format('SELECT pg_temp.handoff_run(%L::JSONB,%L::JSONB)',c,pg_temp.handoff_rechain(jsonb_set(v,ARRAY['verification_receipt','objects','0',k],new_value))),'22023','initial_analysis_input_invalid','changed object '||k) FROM handoff_first CROSS JOIN handoff_object_changes;
SELECT extensions.throws_ok(format('SELECT pg_temp.handoff_run(%L::JSONB,%L::JSONB)',c,jsonb_set(v,path,value)),'22023','initial_analysis_input_invalid','cross-document mismatch '||path::TEXT) FROM handoff_first CROSS JOIN (VALUES
 (ARRAY['verification_receipt','claim','claim_token'],'"ffffffff-ffff-ffff-ffff-ffffffffffff"'::JSONB),
 (ARRAY['verification_receipt','claim_digest'],to_jsonb(repeat('f',64))),
 (ARRAY['transfer_receipt','verification_receipt_digest'],to_jsonb(repeat('f',64))),
 (ARRAY['transfer_receipt','protocol_artifact_digest'],to_jsonb(repeat('f',64))),
 (ARRAY['transfer_receipt','admission_receipt_digest'],to_jsonb(repeat('f',64)))) z(path,value);
-- A coherent alternate synthetic token is intentionally not issuance authentication.
SELECT extensions.is(pg_temp.handoff_run(c,pg_temp.handoff_rechain(jsonb_set(v,'{claim,claim_token}','"ffffffff-ffff-ffff-ffff-ffffffffffff"')))->>'authority','none','alternate self-consistent token proves no stored issuance') FROM handoff_first;
-- Original strict cutoffs and chronology, with nested hashes recomputed.
SELECT extensions.throws_ok(format('SELECT pg_temp.handoff_run(%L::JSONB,%L::JSONB)',c,pg_temp.handoff_rechain(jsonb_set(v,path,value))),'22023','initial_analysis_input_invalid','cutoff equality or time inversion '||path::TEXT) FROM handoff_first CROSS JOIN LATERAL (VALUES
 (ARRAY['claim','issued_at_ms'],v#>'{claim,binding,phase_window,cutoffs,verification_claim}'),
 (ARRAY['claim','issued_at_ms'],to_jsonb(((c->>'manifest')::JSONB->>'authorized_at_ms')::NUMERIC-1)),
 (ARRAY['verification_receipt','authorized_at_ms'],v#>'{claim,binding,phase_window,cutoffs,verification_settlement}'),
 (ARRAY['verification_receipt','authorized_at_ms'],to_jsonb((v#>>'{claim,issued_at_ms}')::NUMERIC-1)),
 (ARRAY['transfer_receipt','authorized_at_ms'],v#>'{claim,binding,phase_window,cutoffs,transfer}'),
 (ARRAY['transfer_receipt','authorized_at_ms'],to_jsonb((v#>>'{verification_receipt,authorized_at_ms}')::NUMERIC-1))) z(path,value);
-- Shape/canonical validation applies to digest-only callers too.
SELECT extensions.throws_ok(format('SELECT internal.initial_media_handoff_proof_digest(%L,%L)',k,internal.initial_canonical(jsonb_set(v->k,CASE WHEN k='verification_receipt' THEN ARRAY['objects'] ELSE ARRAY['verification_receipt','objects'] END,'[]'))),'22023','initial_analysis_input_invalid','empty union digest rejection '||k) FROM handoff_first CROSS JOIN unnest(ARRAY['verification_receipt','transfer_receipt']) k;
SELECT extensions.throws_ok(format('SELECT internal.initial_media_handoff_proof_digest(%L,%L)',k,t),'22023','initial_analysis_input_invalid','noncanonical/invalid bounded document '||k) FROM handoff_first CROSS JOIN unnest(ARRAY['claim','verification_receipt','transfer_receipt']) k CROSS JOIN LATERAL unnest(ARRAY[NULL,'null','{}','[]',repeat('x',CASE k WHEN 'claim' THEN 32769 WHEN 'verification_receipt' THEN 65537 ELSE 98305 END),internal.initial_canonical(v->k)||' ',replace(internal.initial_canonical(v->k),'"version":','"version":0,"version":')]) t;
SELECT extensions.throws_ok(format('SELECT internal.initial_media_handoff_proof_digest(%L,%L)',k,internal.initial_canonical(v->'claim')),'22023','initial_analysis_input_invalid','invalid domain selector') FROM handoff_first CROSS JOIN unnest(ARRAY[NULL,'constructor','other']) k;
SELECT extensions.throws_ok(format('SELECT internal.initial_media_handoff_proof_digest(''claim'',%L)',replace(internal.initial_canonical(v->'claim'),'"issued_at_ms":'||(v#>>'{claim,issued_at_ms}'),'"issued_at_ms":'||value::TEXT)),'22023','initial_analysis_input_invalid','unsafe/negative/fractional/null timestamp') FROM handoff_first CROSS JOIN unnest(ARRAY['9007199254740992'::JSONB,'-1','0.5','null','"bad"']) value;
SELECT extensions.throws_ok(format('SELECT internal.initial_media_handoff_proof_digest(''claim'',%L)',replace(internal.initial_canonical(v->'claim'),'"issued_at_ms":'||(v#>>'{claim,issued_at_ms}'),'"issued_at_ms":-0')),'22023','initial_analysis_input_invalid','negative zero spelling rejected') FROM handoff_first;
SELECT extensions.throws_ok(format('SELECT internal.initial_media_handoff_proof_digest(%L,%L)',k,internal.initial_canonical((v->k)-field)),'22023','initial_analysis_input_invalid','mandatory top-level field '||k||field) FROM handoff_first CROSS JOIN unnest(ARRAY['claim','verification_receipt','transfer_receipt']) k CROSS JOIN LATERAL jsonb_object_keys(v->k) field;
SELECT extensions.throws_ok(format('SELECT internal.initial_media_handoff_proof_digest(%L,%L)',k,internal.initial_canonical((v->k)||'{"unexpected":1}')),'22023','initial_analysis_input_invalid','unknown top-level field '||k) FROM handoff_first CROSS JOIN unnest(ARRAY['claim','verification_receipt','transfer_receipt']) k;
CREATE FUNCTION pg_temp.handoff_extra(c JSONB,v JSONB,k TEXT) RETURNS JSONB LANGUAGE SQL AS $f$
SELECT internal.validate_initial_media_handoff_proof(k,c->>'candidate',c->>'input',c->>'configuration',c->>'funding',c->>'outcome',c->>'installation',c->>'protocol',c->>'destination',c->>'mapping',c->>'media_binding',c->>'accounting',c->>'manifest',internal.initial_canonical(v->'claim'),internal.initial_canonical(v->'verification_receipt'),internal.initial_canonical(v->'transfer_receipt'));
$f$;
SELECT extensions.throws_ok(format('SELECT pg_temp.handoff_extra(%L::JSONB,%L::JSONB,%L)',c,v,k),'22023','initial_analysis_input_invalid','later stage documents forbidden') FROM handoff_first CROSS JOIN unnest(ARRAY['claim','verification_receipt',NULL,'unknown']) k;
SELECT extensions.ok(NOT has_function_privilege(r,s,'EXECUTE'),'API role denied '||r||s) FROM unnest(ARRAY['anon','authenticated','service_role']) r CROSS JOIN unnest(ARRAY['internal.initial_media_handoff_proof_schema()','internal.parse_initial_media_handoff_proof(text,text)','internal.initial_media_handoff_proof_digest(text,text)','internal.validate_initial_media_handoff_proof(text,text,text,text,text,text,text,text,text,text,text,text,text,text,text,text)']) s;
SELECT extensions.throws_ok(format('SET LOCAL ROLE %I; SELECT %s; RESET ROLE',r,call),'42501',NULL,'actual role denial '||r||call) FROM unnest(ARRAY['anon','authenticated','service_role']) r CROSS JOIN unnest(ARRAY['internal.initial_media_handoff_proof_schema()','internal.parse_initial_media_handoff_proof(NULL,NULL)','internal.initial_media_handoff_proof_digest(NULL,NULL)','internal.validate_initial_media_handoff_proof(NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL)']) call;
SELECT extensions.ok(NOT p.prosecdef AND p.proconfig=ARRAY['search_path=""'] AND p.provolatile IN('i','s'),'pure invoker fixed search path '||p.proname) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='internal' AND p.proname IN('initial_media_handoff_proof_schema','parse_initial_media_handoff_proof','initial_media_handoff_proof_digest','validate_initial_media_handoff_proof');
SELECT extensions.is((SELECT initial_analysis_lifecycle_enabled FROM internal.initial_analysis_rollout),FALSE,'activation remains false');
SELECT * FROM extensions.finish();
ROLLBACK;
